// swift-tools-version: 6.2
import PackageDescription

// Platform-neutral code the SynapseNote Apple apps share. The macOS app comes
// first; the iOS and iPadOS apps will use the same targets.
let package = Package(
    name: "SynapseKit",
    platforms: [.macOS(.v26), .iOS(.v26)],
    products: [
        .library(name: "EditingCore", targets: ["EditingCore"]),
    ],
    targets: [
        // Runs the core editing model (packages/core/src/editing-model) in
        // JavaScriptCore. Resources/synapsenote-editing.js is generated by
        // `bun run --filter @nedian0brien/synapsenote-core build:native-bundle`.
        .target(
            name: "EditingCore",
            resources: [.copy("Resources/synapsenote-editing.js")]
        ),
        .testTarget(
            name: "EditingCoreTests",
            dependencies: ["EditingCore"]
        ),
    ]
)
